217	    /// Compress `typeof foo == "undefined"`
218	    ///
219	    /// - `typeof foo == "undefined"` (if foo is not resolved) -> `typeof foo > "u"`
220	    /// - `typeof foo != "undefined"` (if foo is not resolved) -> `typeof foo < "u"`
221	    /// - `typeof foo == "undefined"` -> `foo === undefined`
222	    /// - `typeof foo != "undefined"` -> `foo !== undefined`
223	    /// - `typeof foo.bar == "undefined"` -> `foo.bar === undefined` (for any expression e.g.`typeof (foo + "")`)
224	    /// - `typeof foo.bar != "undefined"` -> `foo.bar !== undefined` (for any expression e.g.`typeof (foo + "")`)
225	    ///
226	    /// Enabled by `compress.typeofs`
227	    pub fn substitute_typeof_undefined(expr: &mut Expression<'a>, ctx: &mut TraverseCtx<'a>) {
228	        let Expression::BinaryExpression(e) = expr else { return };
229	        let Expression::UnaryExpression(unary_expr) = &e.left else { return };
230	        if !unary_expr.operator.is_typeof() {
231	            return;
232	        }
233	        let (new_eq_op, new_comp_op) = match e.operator {
234	            BinaryOperator::Equality | BinaryOperator::StrictEquality => {
235	                (BinaryOperator::StrictEquality, BinaryOperator::GreaterThan)
236	            }
237	            BinaryOperator::Inequality | BinaryOperator::StrictInequality => {
238	                (BinaryOperator::StrictInequality, BinaryOperator::LessThan)
239	            }
240	            _ => return,
241	        };
242	        if !e.right.is_specific_string_literal("undefined") {
243	            return;
244	        }
245	        *expr = if let Expression::Identifier(ident) = &unary_expr.argument
246	            && ctx.is_global_reference(ident)
247	        {
248	            let left = e.left.take_in(ctx.ast);
249	            let right = ctx.ast.expression_string_literal(e.right.span(), "u", None);
250	            ctx.ast.expression_binary(e.span, left, new_comp_op, right)
251	        } else {
252	            let span = e.span;
253	            let Expression::UnaryExpression(unary_expr) = &mut e.left else { return };
254	            ctx.ast.expression_binary(
255	                span,
256	                unary_expr.take_in(ctx.ast).argument,
257	                new_eq_op,
258	                ctx.ast.void_0(e.right.span()),
259	            )
260	        };
261	        ctx.state.changed = true;
262	    }
